  DailyReading(
      179, "Begin Before Conditions Are Perfect", "Ecclesiastes 11:4", [
    ReadingCard("scripture",
        "He who observes the wind won’t sow; and he who regards the clouds won’t reap."),
    ReadingCard("meaning",
